CustomField.formula:
HYPERLINK(
/** 🔗 The Link path is set here 🔗 **/
'/'&BlankValue(Parent_Form_Submission__c,Form_Template__c), 

/** 📝 Display Form Template 📝 **/
IF(Not(IsBlank( Form_Template__c)),Form_Template__r.Name,

/** 🗂️ Display Parent Submission 🗂️ **/
IF(Not(IsBlank(Parent_Form_Submission__c)), 'Submission ('+Name+')',

'Unknown')),
'_self')
